using Microsoft.EntityFrameworkCore;using RetailShop.Application.Finance;using RetailShop.Domain.Finance;using RetailShop.Infrastructure.Finance;using RetailShop.Infrastructure.Persistence;
namespace RetailShop.Tests.Finance;
public sealed class FinanceReportingTests
{
 [Fact] public async Task Ledger_has_correct_opening_running_closing_and_pagination(){await using var db=await Ready();var cash=await A(db,"1110");var capital=await A(db,"3100");await Post(db,new DateOnly(2026,1,1),Guid.NewGuid(),[new(cash.Id,100,0),new(capital.Id,0,100)]);await Post(db,new DateOnly(2026,2,1),Guid.NewGuid(),[new(cash.Id,25,0),new(capital.Id,0,25)]);var r=await new FinanceReportingService(db).GeneralLedgerAsync(cash.Id,new(2026,2,1),new(2026,2,28),1,1);Assert.True(r.Succeeded);Assert.Equal(100,r.Value!.OpeningBalance);Assert.Equal(125,r.Value.ClosingBalance);Assert.Equal(125,r.Value.Movements.Items.Single().RunningBalance);}
 [Fact] public async Task Trial_balance_reconciles_and_includes_inactive_posted_account(){await using var db=await Ready();var cash=await A(db,"1110");var capital=await A(db,"3100");await Post(db,new(2026,1,1),Guid.NewGuid(),[new(cash.Id,100,0),new(capital.Id,0,100)]);cash.SetActive(false);await db.SaveChangesAsync();var r=await new FinanceReportingService(db).TrialBalanceAsync(new(2026,1,1),new(2026,12,31));Assert.Equal(0,r.Value!.Difference);Assert.Contains(r.Value.Rows,x=>x.AccountId==cash.Id&&!x.Active);}
 [Fact] public async Task Cash_flow_eliminates_internal_transfer(){await using var db=await Ready();var cash=await A(db,"1110");var bank=await A(db,"1140");db.FinancialAccounts.AddRange(new("C","Cash",FinancialAccountType.Cash,cash.Id),new("B","Bank",FinancialAccountType.Bank,bank.Id));await db.SaveChangesAsync();await new JournalPostingService(db,TimeProvider.System).PostAsync(new(new(2026,1,2),"FundTransfer",Guid.NewGuid(),"Transfer",null,[new(bank.Id,20,0),new(cash.Id,0,20)]),Guid.NewGuid());var r=await new FinanceReportingService(db).CashFlowAsync(new(2026,1,1),new(2026,1,31));Assert.Equal(0,r.Value!.NetMovement);}
 private static async Task<RetailShopDbContext> Ready(){var db=new RetailShopDbContext(new DbContextOptionsBuilder<RetailShopDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options);await new FinanceInitializer(db).InitialiseAsync();db.FiscalPeriods.Add(new("FY",new(2026,1,1),new(2026,12,31)));await db.SaveChangesAsync();return db;}private static Task<Account>A(RetailShopDbContext db,string c)=>db.Accounts.SingleAsync(x=>x.Code==c);private static Task Post(RetailShopDbContext db,DateOnly d,Guid id,IReadOnlyCollection<JournalLineRequest> l)=>new JournalPostingService(db,TimeProvider.System).PostAsync(new(d,"Test",id,"Test",null,l),Guid.NewGuid());
}
